python - <<'PY'
import json,subprocess,collections
D=json.load(open('/tmp/candidate.json'))['diagrams']; f=collections.defaultdict(list)
for d in D:
 for m in d['mappings']:f[m['path']].append((d['diagramId'],m['node'],m['startLine'],m['endLine']))
with open('/tmp/verified-ranges.txt','w') as o:
 for path,spans in f.items():
  lines=subprocess.check_output(['nl','-ba',path],text=True).splitlines()
  for diagram,node,a,b in spans:
   o.write(f'### {diagram} {node} {path} {a}-{b}\n');o.write('\n'.join(lines[a-1:b])+'\n')
print('ranges',sum(map(len,f.values())),'files',len(f),'read lines',sum(1 for _ in open('/tmp/verified-ranges.txt')))
PY
